mod common;

use hmac::{Hmac, Mac};
use receivify::webhooks::{self, VerifyOptions, WebhookError, DEFAULT_TOLERANCE_SECONDS, EVENTS};
use receivify::{ForwardEventData, InvoiceStatus};
use sha2::Sha256;

const CURRENT: &str = "whsec_current_secret";
const PREVIOUS: &str = "whsec_previous_secret";
const T: i64 = 1_767_225_600;

// Golden vectors generated by the reference Node SDK over these exact bytes (shared with the
// C++ SDK's test suite).
const GOLDEN_BODY: &str = concat!(
    r#"{"event":"invoice.paid","sequence":42,"created_at":"2026-01-01T00:00:00.000Z","data":"#,
    r#"{"id":"11111111-2222-3333-4444-555555555555","reference":"order-1","status":"paid","#,
    r#""amount_expected":"2100000000000000000000000","amount_received":"2100000000000000000000000","#,
    r#""address":"bc1qexample","paid_at":"2026-01-01T00:00:00.000Z"}}"#
);
const GOLDEN_CURRENT_SIG: &str = "a3dde1183a18417f13d04fd50823ce41bdb0ce3ee2176455d20a44f26679f6c0";
const GOLDEN_PREVIOUS_SIG: &str =
    "928a4d6dfcafa3bf5ec4b923face2f24eaeb2aff36bf70e4faa65ab7a8a24c9a";

/// Sign independently of the SDK: HMAC-SHA256 hex over "<t>.<body>".
fn independent_sign(body: &[u8], secret: &str, t: i64) -> String {
    let mut mac = Hmac::<Sha256>::new_from_slice(secret.as_bytes()).unwrap();
    mac.update(format!("{t}.").as_bytes());
    mac.update(body);
    let sig: String = mac
        .finalize()
        .into_bytes()
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect();
    format!("t={t},v1={sig}")
}

fn at(t: i64) -> VerifyOptions {
    VerifyOptions::default().now(t)
}

fn body() -> &'static [u8] {
    GOLDEN_BODY.as_bytes()
}

#[test]
fn cross_sdk_golden_vector_current_secret() {
    let header = format!("t={T},v1={GOLDEN_CURRENT_SIG}");
    assert!(webhooks::verify(
        body(),
        &header,
        &[CURRENT, PREVIOUS],
        at(T)
    ));
}

#[test]
fn cross_sdk_golden_vector_previous_secret() {
    let header = format!("t={T},v1={GOLDEN_PREVIOUS_SIG}");
    assert!(webhooks::verify(
        body(),
        &header,
        &[CURRENT, PREVIOUS],
        at(T)
    ));
}

#[test]
fn cross_sdk_golden_vector_wrong_secret_is_rejected() {
    let header = format!("t={T},v1={GOLDEN_CURRENT_SIG}");
    assert!(!webhooks::verify(body(), &header, &[PREVIOUS], at(T)));
}

#[test]
fn sign_reproduces_the_node_signature_and_an_independent_hmac() {
    assert_eq!(
        webhooks::sign(body(), CURRENT, T),
        format!("t={T},v1={GOLDEN_CURRENT_SIG}")
    );
    assert_eq!(
        webhooks::sign(body(), CURRENT, T),
        independent_sign(body(), CURRENT, T)
    );
}

#[test]
fn verifies_the_current_secret() {
    let header = independent_sign(body(), CURRENT, T);
    assert!(webhooks::verify(body(), &header, &[CURRENT], at(T)));
}

#[test]
fn verifies_the_previous_secret_during_rotation() {
    let header = independent_sign(body(), PREVIOUS, T);
    assert!(webhooks::verify(
        body(),
        &header,
        &[CURRENT, PREVIOUS],
        at(T)
    ));
    assert!(!webhooks::verify(body(), &header, &[CURRENT], at(T)));
}

#[test]
fn accepts_owned_strings_as_secrets() {
    let secrets: Vec<String> = vec![CURRENT.to_string()];
    let header = independent_sign(body(), CURRENT, T);
    assert!(webhooks::verify(body(), &header, &secrets, at(T)));
}

#[test]
fn rejects_a_tampered_body() {
    let header = independent_sign(body(), CURRENT, T);
    let tampered = GOLDEN_BODY.replace("2100000000000000000000000", "2100000000000000000000001");
    assert_eq!(
        webhooks::verify_detailed(tampered.as_bytes(), &header, &[CURRENT], at(T)),
        Err(WebhookError::NoMatch)
    );
}

#[test]
fn a_reserialised_body_fails_which_is_why_raw_bytes_matter() {
    let header = independent_sign(body(), CURRENT, T);
    let v: serde_json::Value = serde_json::from_str(GOLDEN_BODY).unwrap();
    let pretty = serde_json::to_string_pretty(&v).unwrap();
    assert!(!webhooks::verify(
        pretty.as_bytes(),
        &header,
        &[CURRENT],
        at(T)
    ));
}

#[test]
fn rejects_a_stale_timestamp_with_the_default_tolerance() {
    let header = independent_sign(body(), CURRENT, T - 3600);
    let r = webhooks::verify_detailed(body(), &header, &[CURRENT], at(T));
    assert!(matches!(
        r,
        Err(WebhookError::StaleTimestamp {
            tolerance_seconds: 300,
            ..
        })
    ));
    assert_eq!(r.unwrap_err().reason(), "stale_timestamp");
}

#[test]
fn rejects_a_timestamp_too_far_in_the_future() {
    let header = independent_sign(body(), CURRENT, T + 301);
    assert!(!webhooks::verify(body(), &header, &[CURRENT], at(T)));
}

#[test]
fn accepts_a_timestamp_at_the_edge_of_the_window() {
    let header = independent_sign(body(), CURRENT, T - DEFAULT_TOLERANCE_SECONDS as i64);
    assert!(webhooks::verify(body(), &header, &[CURRENT], at(T)));
}

#[test]
fn a_custom_tolerance_and_zero_to_disable() {
    let header = independent_sign(body(), CURRENT, T - 3600);
    assert!(webhooks::verify(
        body(),
        &header,
        &[CURRENT],
        at(T).tolerance_seconds(7200)
    ));
    assert!(!webhooks::verify(
        body(),
        &header,
        &[CURRENT],
        at(T).tolerance_seconds(60)
    ));
    assert!(webhooks::verify(
        body(),
        &header,
        &[CURRENT],
        at(T).tolerance_seconds(0)
    ));
}

#[test]
fn uses_the_system_clock_by_default() {
    let now = webhooks::now_unix();
    let header = independent_sign(body(), CURRENT, now);
    assert!(webhooks::verify(
        body(),
        &header,
        &[CURRENT],
        VerifyOptions::default()
    ));
    let old = independent_sign(body(), CURRENT, now - 3600);
    assert!(!webhooks::verify(
        body(),
        &old,
        &[CURRENT],
        VerifyOptions::default()
    ));
}

#[test]
fn no_secrets_is_a_clean_false() {
    let header = independent_sign(body(), CURRENT, T);
    let none: [&str; 0] = [];
    assert_eq!(
        webhooks::verify_detailed(body(), &header, &none, at(T)),
        Err(WebhookError::NoSecrets)
    );
    assert!(!webhooks::verify(body(), &header, &[""], at(T)));
}

#[test]
fn malformed_headers_are_bad_header() {
    for h in [
        "",
        "garbage",
        "t=,v1=abc",
        "v1=abcdef",
        &format!("t={T}"),
        &format!("t=-{T},v1=00"),
        &format!("t={T}x,v1=00"),
        "t=99999999999999999999999,v1=00",
    ] {
        assert_eq!(
            webhooks::verify_detailed(body(), h, &[CURRENT], at(T)),
            Err(WebhookError::BadHeader),
            "header {h:?}"
        );
    }
}

#[test]
fn non_hex_or_wrong_length_signatures_are_rejected_without_panicking() {
    for sig in ["zz", "abc", "00", &"0".repeat(64), &"g".repeat(64)] {
        let h = format!("t={T},v1={sig}");
        assert!(!webhooks::verify(body(), &h, &[CURRENT], at(T)));
    }
}

#[test]
fn any_of_several_v1_values_may_match_and_whitespace_is_tolerated() {
    let good = independent_sign(body(), CURRENT, T);
    let sig = good.split("v1=").nth(1).unwrap();
    let h = format!("t={T}, v1={} , v1={sig}", "0".repeat(64));
    assert!(webhooks::verify(body(), &h, &[CURRENT], at(T)));
    let upper = format!("t={T},v1={}", sig.to_uppercase());
    assert!(webhooks::verify(body(), &upper, &[CURRENT], at(T)));
}

#[test]
fn the_raw_timestamp_text_is_what_is_signed() {
    // "0001767225600" and "1767225600" are different signed messages.
    let padded = format!("t=000{T},v1={GOLDEN_CURRENT_SIG}");
    assert!(!webhooks::verify(body(), &padded, &[CURRENT], at(T)));
}

#[test]
fn parse_returns_the_envelope_and_keeps_money_exact() {
    let header = independent_sign(body(), CURRENT, T);
    let ev = webhooks::parse(body(), &header, &[CURRENT], at(T)).unwrap();
    assert_eq!(ev.event, "invoice.paid");
    assert_eq!(ev.sequence, 42);
    assert_eq!(ev.created_at, "2026-01-01T00:00:00.000Z");
    assert!(ev.is_invoice_event());
    assert!(!ev.is_forward_event());
    let data = ev.invoice_data().unwrap();
    assert_eq!(data.status, InvoiceStatus::Paid);
    assert_eq!(data.amount_expected, "2100000000000000000000000");
    assert_eq!(data.reference.as_deref(), Some("order-1"));
}

#[test]
fn parse_reports_the_verification_reason() {
    let header = independent_sign(body(), PREVIOUS, T);
    let err = webhooks::parse(body(), &header, &[CURRENT], at(T)).unwrap_err();
    assert_eq!(err, WebhookError::NoMatch);
    assert_eq!(err.reason(), "no_match");
    let as_sdk_error: receivify::Error = err.into();
    assert!(matches!(as_sdk_error, receivify::Error::Webhook(_)));
}

#[test]
fn parse_rejects_a_verified_body_that_is_not_json_or_not_an_envelope() {
    let not_json = b"not json";
    let h = independent_sign(not_json, CURRENT, T);
    assert!(matches!(
        webhooks::parse(not_json, &h, &[CURRENT], at(T)),
        Err(WebhookError::BadJson(_))
    ));
    for b in [&b"[1,2]"[..], br#"{"sequence":1}"#, br#"{"event":5}"#] {
        let h = independent_sign(b, CURRENT, T);
        assert_eq!(
            webhooks::parse(b, &h, &[CURRENT], at(T)),
            Err(WebhookError::BadEnvelope)
        );
    }
}

#[test]
fn parse_tolerates_the_legacy_invoice_shape_and_unknown_events() {
    let b = br#"{"event":"invoice.future_thing","invoice":{"id":"x"},"new_key":true}"#;
    let ev = webhooks::parse_unverified(b).unwrap();
    assert_eq!(ev.event, "invoice.future_thing");
    assert_eq!(ev.sequence, 0);
    assert_eq!(ev.data["id"], "x");
    assert_eq!(ev.extra["new_key"], true);
}

#[test]
fn a_forward_event_carries_cryptapi_shaped_data() {
    let b = br#"{"event":"forward.deferred","sequence":7,"created_at":"c","data":{"forward_id":"f","ticker":"eth","address_in":"0xin","address_out":"0xout","txid_in":"0xt","txid_out":null,"value":"50000000000000000000","value_forwarded":"49500000000000000000","fee":"500000000000000000","confirmations":12,"pending":false,"reason":"uneconomical","detail":"Fees exceed value."}}"#;
    let h = independent_sign(b, CURRENT, T);
    let ev = webhooks::parse(b, &h, &[CURRENT], at(T)).unwrap();
    assert!(ev.is_forward_event());
    let d: ForwardEventData = ev.forward_data().unwrap();
    assert_eq!(d.value, "50000000000000000000");
    assert_eq!(d.reason.as_deref(), Some("uneconomical"));
    assert_eq!(d.txid_out, None);
}

#[test]
fn event_family_helpers_and_the_full_registry() {
    assert!(webhooks::is_invoice_event("invoice.paid"));
    assert!(webhooks::is_invoice_event("sweep.sent"));
    assert!(webhooks::is_invoice_event("test"));
    assert!(webhooks::is_forward_event("forward.detected"));
    assert!(!webhooks::is_forward_event("invoice.paid"));
    assert_eq!(EVENTS.len(), 16);
    for e in [
        "forward.detected",
        "forward.deferred",
        "forward.reversed",
        "forward.failed",
        "invoice.partial_expired",
    ] {
        assert!(EVENTS.contains(&e), "{e}");
    }
}

#[test]
fn the_client_verifies_against_its_configured_rotation_list() {
    let fake = common::Fake::new();
    let client = fake
        .builder()
        .webhook_secrets(vec![CURRENT.to_string(), PREVIOUS.to_string()])
        .build()
        .unwrap();
    let now = webhooks::now_unix();
    let by_prev = independent_sign(body(), PREVIOUS, now);
    assert!(client.verify_webhook(body(), &by_prev));
    assert_eq!(client.parse_webhook(body(), &by_prev).unwrap().sequence, 42);
    let by_other = independent_sign(body(), "whsec_other", now);
    assert!(!client.verify_webhook(body(), &by_other));

    let no_secrets = fake.client();
    assert_eq!(
        no_secrets.parse_webhook(body(), &by_prev).unwrap_err(),
        WebhookError::NoSecrets
    );
}
